package com.powercms.cms.delivery;
import org.junit.jupiter.api.Test; import java.util.concurrent.*; import static org.junit.jupiter.api.Assertions.*;
class RenderDatasetCacheP25Test {
 @Test void systemAndApplicationAreIndependent(){var c=new RenderDatasetCache(4);c.getOrLoad(RenderDatasetCache.Region.SYSTEM,"x",true,()->"system");c.getOrLoad(RenderDatasetCache.Region.APPLICATION,"x",true,()->"application");assertEquals("system",c.getOrLoad(RenderDatasetCache.Region.SYSTEM,"x",true,()->"bad"));assertEquals("application",c.getOrLoad(RenderDatasetCache.Region.APPLICATION,"x",true,()->"bad"));}
 @Test void previewBypasses(){var c=new RenderDatasetCache(4);assertEquals("a",c.getOrLoad(RenderDatasetCache.Region.SYSTEM,"x",false,()->"a"));assertEquals("b",c.getOrLoad(RenderDatasetCache.Region.SYSTEM,"x",false,()->"b"));assertEquals(2,c.stats().bypasses());}
 @Test void concurrentAccessOrderAndPrefixInvalidationAreSafe() throws Exception {var c=new RenderDatasetCache(64);ExecutorService pool=Executors.newFixedThreadPool(8);try{var tasks=new java.util.ArrayList<Callable<Void>>();for(int t=0;t<8;t++){int thread=t;tasks.add(()->{for(int i=0;i<3000;i++){String key=(i%2==0?"remove:":"keep:")+((i+thread)%100);c.getOrLoad(RenderDatasetCache.Region.APPLICATION,key,true,()->key);if(i%17==0)c.invalidatePrefix(RenderDatasetCache.Region.APPLICATION,"remove:");}return null;});}for(Future<Void> f:pool.invokeAll(tasks))f.get();}finally{pool.shutdownNow();}assertTrue(c.stats().sizes().get("APPLICATION")<=64);c.invalidatePrefix(RenderDatasetCache.Region.APPLICATION,"remove:");assertDoesNotThrow(c::stats);}
}
